<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Tournament extends Model { protected $fillable=['organizer_id','club_id','venue_id','city_id','name','description','format','status','start_date','end_date','registration_deadline','max_players','entry_fee']; protected $casts=['start_date'=>'date','end_date'=>'date','registration_deadline'=>'date']; public function organizer(){return $this->belongsTo(User::class,'organizer_id');} public function club(){return $this->belongsTo(Club::class);} public function venue(){return $this->belongsTo(Venue::class);} public function city(){return $this->belongsTo(City::class);} public function registrations(){return $this->hasMany(Registration::class);} public function confirmedRegistrations(){return $this->registrations()->where('status','confirmed');} public function registrationsOpen():bool{return $this->status==='approved' && (!$this->registration_deadline || now()->startOfDay()->lte($this->registration_deadline));} }
